// Ensure current node has neighbors
current_node->find_neighbors();

// Iterate through all neighbors of current node
for (auto* neighbor : current_node->neighbors) {
    // Skip if neighbor has already been visited
    if (neighbor->visited) {
        continue;
    }

    // Calculate g value: distance from start to neighbor through current node
    float g_value = current_node->g_value + current_node->distance(*neighbor);

    // Calculate h value: heuristic distance from neighbor to end node
    float h_value = neighbor->distance(*end_node);

    // If the calculated g value is better than the existing one
    if (g_value < neighbor->g_value) {
        // Update neighbor's g and h values
        neighbor->g_value = g_value;
        neighbor->h_value = h_value;

        // Set current node as parent of neighbor
        neighbor->parent = current_node;

        // Add neighbor to open list
        open_list.push_back(neighbor);
    }
}

